package com.tfasplitstracker;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** A client-thread snapshot of the game's HUD, never a wall-clock extrapolation. */
final class TfaLiveState
{
	private static final Pattern TIME = Pattern.compile("(?<![\\d:])(\\d+:\\d{2}(?::\\d{2})?(?:\\.\\d{1,3})?)(?![\\d:])");
	static final TfaLiveState UNAVAILABLE = new TfaLiveState(false, "", -1);
	final boolean inRaid;
	final String status;
	final long elapsed;

	TfaLiveState(boolean inRaid, String status, long elapsed)
	{
		this.inRaid = inRaid;
		this.status = status;
		this.elapsed = elapsed;
	}

	static String clean(String text)
	{
		return text == null ? "" : text.replaceAll("<[^>]*>", "").replace('\u00a0', ' ').trim();
	}

	static long parseClock(String text)
	{
		Matcher matcher = TIME.matcher(clean(text));
		return matcher.find() ? TfaTracker.parseTime(matcher.group(1)) : -1;
	}
}

package com.tfasplitstracker;

/** Client-observed phase boundaries, timed in game ticks; never replayed from old chat. */
final class TfaOcellus
{
	static final int VINES_NPC = 16674;
	static final int PORTALS_NPC = 16675;
	static final int QUADRANTS_NPC = 16677;
	static final int DESTROY_QUADRANT_ANIMATION = 14859;
	private TfaRaid.Split split;
	private int phase;
	private int fightTick = -1;
	private int phaseTick = -1;
	private int quadrantDestructions;
	private int lastDestructionTick = -1;

	void begin(TfaRaid.Split next, int tick)
	{
		if (split == next)
		{
			if (fightTick < 0 && phase == 1 && next.phases.size() == 1)
			{
				fightTick = tick;
				phaseTick = tick;
			}
			return;
		}
		attach(next);
		// Existing partial records must not acquire a fabricated start after reloading.
		if (!next.phases.isEmpty()) { return; }
		fightTick = tick;
		phaseTick = tick;
		phase = 1;
		addThrough(1);
	}

	boolean observe(TfaRaid.Split next, int npcId, int tick, boolean boundary)
	{
		int target = npcId == VINES_NPC ? 1 : npcId == PORTALS_NPC ? 2 : npcId == QUADRANTS_NPC ? 3 : 0;
		if (target == 0) { return false; }
		if (split != next) { attach(next); }
		return transition(target, tick, boundary);
	}

	boolean destroyQuadrant(TfaRaid.Split next, int tick)
	{
		if (split != next || phase != 3 || tick == lastDestructionTick) { return false; }
		lastDestructionTick = tick;
		quadrantDestructions++;
		return quadrantDestructions == 3 && transition(4, tick, true);
	}

	private void attach(TfaRaid.Split next)
	{
		split = next;
		phase = next.phases.isEmpty() ? 0 : next.phases.get(next.phases.size() - 1).number;
		fightTick = -1;
		phaseTick = -1;
		quadrantDestructions = 0;
		lastDestructionTick = -1;
	}

	private boolean transition(int target, int tick, boolean boundary)
	{
		if (target <= phase || split.duration >= 0) { return false; }
		if (boundary && phase > 0 && target == phase + 1 && phaseTick >= 0 && tick >= phaseTick)
		{
			TfaRaid.Phase previous = split.phases.get(phase - 1);
			previous.duration = (tick - phaseTick) * 600L;
			previous.cumulative = fightTick < 0 ? -1 : (tick - fightTick) * 600L;
		}
		addThrough(target);
		phase = target;
		// First seeing an already-active NPC does not establish that phase's start.
		phaseTick = boundary && target > 1 ? tick : -1;
		return true;
	}

	private void addThrough(int target)
	{
		while (split.phases.size() < target)
		{
			TfaRaid.Phase record = new TfaRaid.Phase();
			record.number = split.phases.size() + 1;
			split.phases.add(record);
		}
	}

	static void finish(TfaRaid.Split split)
	{
		if (split.phases.size() != 4) { return; }
		long endOfThird = split.phases.get(2).cumulative;
		if (endOfThird < 0 || split.duration < endOfThird) { return; }
		TfaRaid.Phase last = split.phases.get(3);
		last.duration = split.duration - endOfThird;
		last.cumulative = split.duration;
	}

	static String label(int phase)
	{
		switch (phase)
		{
			case 1: return "P1 Vines";
			case 2: return "P2 Portals";
			case 3: return "P3 Quadrants";
			case 4: return "P4 Prayer switches";
			default: return "Unknown phase";
		}
	}
}

package com.tfasplitstracker;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/** Frozen server splits from one completed run, rather than a sum of best rooms. */
final class TfaPersonalBest
{
	int scale;
	long total;
	List<TfaRaid.Split> splits = new ArrayList<>();

	static void select(TfaRaid raid, List<TfaRaid> history)
	{
		int scale = raid.scale();
		if (scale <= 0 || raid.personalBestSelected && raid.personalBestScale == scale) { return; }
		raid.personalBestSelected = true;
		raid.personalBestScale = scale;
		raid.personalBest = null;
		history.stream().filter(r -> !r.id.equals(raid.id) && r.scale() == scale
			&& "Completed".equals(r.status) && valid(r) && r.updated <= raid.started)
			.min(Comparator.comparingLong(r -> r.total)).ifPresent(best ->
			{
				TfaPersonalBest reference = new TfaPersonalBest();
				reference.scale = scale;
				reference.total = best.total;
				reference.splits.addAll(best.copy().splits);
				raid.personalBest = reference;
			});
	}

	private static boolean valid(TfaRaid raid)
	{
		if (!raid.completeSplits() || raid.total < 0) { return false; }
		long previous = 0;
		for (int i = 0; i < raid.splits.size(); i++)
		{
			TfaRaid.Split split = raid.splits.get(i);
			TfaRoom room = TfaRoom.find(split.room);
			if (room == null || room.stage != i + 1 || split.cumulative < previous + split.duration) { return false; }
			previous = split.cumulative;
		}
		return raid.total >= previous;
	}

	TfaRaid.Split stage(TfaRaid.Split split)
	{
		TfaRoom room = TfaRoom.find(split.room);
		return room == null ? null : splits.stream().filter(s ->
			TfaRoom.find(s.room) != null && TfaRoom.find(s.room).stage == room.stage).findFirst().orElse(null);
	}

	String comparison(TfaRaid.Split split)
	{
		TfaRaid.Split reference = stage(split);
		if (reference == null || split.duration < 0 || split.cumulative < 0) { return ""; }
		String room = reference.room.equals(split.room) ? "room " + delta(split.duration - reference.duration) : "different boss";
		return room + ", raid " + delta(split.cumulative - reference.cumulative);
	}

	static String delta(long millis)
	{
		return (millis > 0 ? "+" : millis < 0 ? "-" : "") + TfaRaid.time(Math.abs(millis));
	}

	TfaRaid.Phase phase(TfaRaid.Split split, int number)
	{
		TfaRaid.Split reference = stage(split);
		return reference == null ? null : reference.phases.stream()
			.filter(p -> p.number == number && p.duration >= 0).findFirst().orElse(null);
	}

	static String status(TfaRaid raid)
	{
		if (raid.scale() <= 0) { return "PB: waiting for party"; }
		return raid.personalBest == null ? "No recorded PB for scale " + raid.scale()
			: "Scale " + raid.personalBest.scale + " PB: " + TfaRaid.time(raid.personalBest.total);
	}
}

package com.tfasplitstracker;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.UUID;

/** Persisted server timings. A negative duration means that no completion was received. */
final class TfaRaid
{
	String id = UUID.randomUUID().toString();
	long started;
	long updated;
	long total = -1;
	String status = "In progress";
	int teamSize;
	int observedTeamSize;
	boolean personalBestSelected;
	int personalBestScale;
	TfaPersonalBest personalBest;
	List<String> members = new ArrayList<>();
	List<Split> splits = new ArrayList<>();

	TfaRaid copy()
	{
		TfaRaid copy = new TfaRaid();
		copy.id = id;
		copy.started = started;
		copy.updated = updated;
		copy.total = total;
		copy.status = status;
		copy.teamSize = teamSize;
		copy.observedTeamSize = observedTeamSize;
		// The PB snapshot is immutable after selection and survives history edits.
		copy.personalBestSelected = personalBestSelected;
		copy.personalBestScale = personalBestScale;
		copy.personalBest = personalBest;
		copy.members.addAll(members);
		for (Split split : splits)
		{
			Split cloned = new Split();
			cloned.room = split.room;
			cloned.started = split.started;
			cloned.duration = split.duration;
			cloned.cumulative = split.cumulative;
			for (Phase phase : split.phases)
			{
				Phase clonedPhase = new Phase();
				clonedPhase.number = phase.number;
				clonedPhase.duration = phase.duration;
				clonedPhase.cumulative = phase.cumulative;
				cloned.phases.add(clonedPhase);
			}
			copy.splits.add(cloned);
		}
		return copy;
	}

	int scale()
	{
		return teamSize > 0 ? teamSize : observedTeamSize;
	}

	static final class Split
	{
		String room;
		long started;
		long duration = -1;
		long cumulative = -1;
		List<Phase> phases = new ArrayList<>();
	}

	static final class Phase
	{
		int number;
		long duration = -1;
		long cumulative = -1;
	}

	boolean active()
	{
		return "In progress".equals(status);
	}

	long combatTime()
	{
		return splits.stream().filter(s -> s.duration >= 0).mapToLong(s -> s.duration).sum();
	}

	boolean completeSplits()
	{
		return splits.size() == 5 && splits.stream().allMatch(s -> s.duration >= 0)
			&& "Archive Guardian".equals(splits.get(0).room)
			&& "Ocellus".equals(splits.get(4).room);
	}

	static String time(long millis)
	{
		if (millis < 0)
		{
			return "--:--";
		}
		return String.format(Locale.ROOT, "%d:%02d.%02d", millis / 60000, millis / 1000 % 60, millis / 10 % 100);
	}
}

package com.tfasplitstracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.stream.Collectors;
import javax.swing.BorderFactory;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JSplitPane;
import javax.swing.JTable;
import javax.swing.JTextField;
import javax.swing.JTextArea;
import javax.swing.ListSelectionModel;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import javax.swing.table.AbstractTableModel;
import javax.swing.table.DefaultTableCellRenderer;

final class TfaRaidComparisonPanel extends JPanel
{
	private static final Color BACKGROUND = new Color(30, 30, 30);
	private static final Color CARD = new Color(39, 39, 39);
	private static final Color TEXT = new Color(225, 225, 225);
	private static final Color MUTED = new Color(165, 165, 165);
	private static final Color FASTER = new Color(120, 210, 150);
	private static final Color SLOWER = new Color(235, 135, 135);
	private static final Font UI_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 14);
	private static final Font SMALL_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 13);
	private static final Font TIME_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 16);
	private static final Font DELTA_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 14);
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("MMM d, yyyy HH:mm:ss").withZone(ZoneId.systemDefault());
	private static final DateTimeFormatter COLUMN_DATE = DateTimeFormatter.ofPattern("MMM d HH:mm").withZone(ZoneId.systemDefault());
	private final Set<String> selected = new LinkedHashSet<>();
	private List<TfaRaid> raids = new ArrayList<>();
	private List<TfaRaid> filtered = new ArrayList<>();
	private final JTextField search = new JTextField();
	private final JComboBox<String> teamSize = new JComboBox<>(new String[]{"All team sizes", "Solo", "2 players", "3 players", "4 players", "5 players", "6 players", "7 players", "8 players"});
	private final JLabel count = new JLabel();
	private final JComboBox<Choice> baseline = new JComboBox<>();
	private final SelectionModel selectionModel = new SelectionModel();
	private final JTable selection = new JTable(selectionModel);
	final ComparisonModel comparisonModel = new ComparisonModel();
	private final JTable comparison = new JTable(comparisonModel);
	private boolean updating;
	private boolean initialized;

	TfaRaidComparisonPanel(List<TfaRaid> savedRaids)
	{
		super(new BorderLayout(12, 12));
		setBackground(BACKGROUND);
		setBorder(BorderFactory.createEmptyBorder(16, 16, 16, 16));
		JPanel title = new JPanel(new BorderLayout(0, 6));
		title.setOpaque(false);
		JLabel heading = new JLabel("Compare Raids");
		heading.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 24));
		heading.setForeground(TEXT);
		title.add(heading, BorderLayout.NORTH);
		count.setForeground(MUTED);
		count.setFont(UI_FONT);
		title.add(count, BorderLayout.SOUTH);
		add(title, BorderLayout.NORTH);

		JPanel picker = new JPanel(new BorderLayout(0, 8));
		picker.setOpaque(false);
		search.putClientProperty("JTextField.placeholderText", "Find a date, player or raid status...");
		search.setName("comparisonRaidSearch");
		search.setToolTipText("Filter saved raids by date, party member, status or team size");
		search.setBackground(CARD);
		search.setForeground(TEXT);
		search.setCaretColor(TEXT);
		search.setFont(UI_FONT);
		search.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(57, 57, 57)),
			BorderFactory.createEmptyBorder(6, 8, 6, 8)));
		JPanel filters = new JPanel(new BorderLayout(0, 6));
		filters.setOpaque(false);
		teamSize.setName("comparisonTeamSize");
		teamSize.setFont(UI_FONT);
		teamSize.setForeground(TEXT);
		teamSize.setBackground(CARD);
		teamSize.setToolTipText("Filter the saved raid list by team size; selected comparisons stay selected");
		teamSize.addActionListener(e -> filter());
		filters.add(teamSize, BorderLayout.NORTH);
		filters.add(search, BorderLayout.SOUTH);
		picker.add(filters, BorderLayout.NORTH);
		styleTable(selection);
		selection.setName("comparisonRaidList");
		selection.setRowHeight(54);
		selection.getColumnModel().getColumn(0).setMaxWidth(30);
		selection.getColumnModel().getColumn(0).setMinWidth(30);
		selection.setDefaultRenderer(String.class, new DefaultTableCellRenderer()
		{
			private final JTextArea text = new JTextArea();

			@Override
			public Component getTableCellRendererComponent(JTable table, Object value, boolean selectedRow, boolean focus, int row, int column)
			{
				TfaRaid raid = filtered.get(row);
				int team = raid.teamSize > 0 ? raid.teamSize : raid.members.size();
				text.setText(DATE.format(Instant.ofEpochMilli(raid.started)) + "\n" + raid.status + " · " + team + " players · " + TfaRaid.time(raid.total));
				text.setFont(SMALL_FONT);
				text.setBackground(selectedRow ? table.getSelectionBackground() : CARD);
				text.setForeground(TEXT);
				text.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
				text.setToolTipText(details(raid));
				return text;
			}
		});
		picker.add(scroll(selection), BorderLayout.CENTER);
		JLabel limit = new JLabel("Select up to 5 raids. Uncheck to swap.");
		limit.setForeground(MUTED);
		limit.setFont(SMALL_FONT);
		picker.add(limit, BorderLayout.SOUTH);
		picker.setMinimumSize(new Dimension(240, 180));

		JPanel results = new JPanel(new BorderLayout(0, 10));
		results.setOpaque(false);
		JPanel controls = new JPanel(new BorderLayout(8, 0));
		controls.setOpaque(false);
		JLabel baselineLabel = new JLabel("Compare against");
		baselineLabel.setForeground(TEXT);
		baselineLabel.setFont(UI_FONT);
		controls.add(baselineLabel, BorderLayout.WEST);
		baseline.setBackground(CARD);
		baseline.setForeground(TEXT);
		baseline.setFont(UI_FONT);
		controls.add(baseline, BorderLayout.CENTER);
		results.add(controls, BorderLayout.NORTH);
		styleTable(comparison);
		comparison.setName("comparisonTimings");
		comparison.setRowHeight(48);
		comparison.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);
		comparison.setDefaultRenderer(Object.class, new TimingRenderer());
		comparison.getTableHeader().setReorderingAllowed(false);
		results.add(scroll(comparison), BorderLayout.CENTER);
		JLabel legend = new JLabel("Green = faster   |   Red = slower   |   — = missing   |   Hover for details");
		legend.setForeground(MUTED);
		legend.setFont(SMALL_FONT);
		results.add(legend, BorderLayout.SOUTH);
		JSplitPane split = new JSplitPane(JSplitPane.HORIZONTAL_SPLIT, picker, results);
		split.setBorder(BorderFactory.createEmptyBorder());
		split.setOpaque(false);
		split.setDividerLocation(330);
		split.setResizeWeight(0);
		add(split, BorderLayout.CENTER);
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			public void insertUpdate(DocumentEvent event) { filter(); }
			public void removeUpdate(DocumentEvent event) { filter(); }
			public void changedUpdate(DocumentEvent event) { filter(); }
		});
		baseline.addActionListener(e ->
		{
			if (!updating)
			{
				Choice choice = (Choice) baseline.getSelectedItem();
				comparisonModel.baselineId = choice == null ? null : choice.raid.id;
				comparisonModel.fireTableDataChanged();
				resizeTimingRows();
			}
		});
		setRaids(savedRaids);
	}

	@Override
	public void paint(Graphics graphics)
	{
		Graphics2D smooth = (Graphics2D) graphics.create();
		smooth.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		smooth.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		super.paint(smooth);
		smooth.dispose();
	}

	void setRaids(List<TfaRaid> savedRaids)
	{
		raids = savedRaids.stream().filter(r -> !r.active()).map(TfaRaid::copy)
			.sorted(Comparator.comparingLong((TfaRaid r) -> r.started).reversed()).collect(Collectors.toList());
		Set<String> available = raids.stream().map(r -> r.id).collect(Collectors.toSet());
		selected.retainAll(available);
		if (!initialized)
		{
			raids.stream().limit(2).forEach(r -> selected.add(r.id));
			initialized = true;
		}
		filter();
		rebuildComparison();
	}

	boolean selectRaid(String id, boolean checked)
	{
		if (checked)
		{
			if (selected.size() >= 5 || raids.stream().noneMatch(r -> r.id.equals(id)))
			{
				return false;
			}
			selected.add(id);
		}
		else
		{
			selected.remove(id);
		}
		selectionModel.fireTableDataChanged();
		rebuildComparison();
		return true;
	}

	void setBaseline(String id)
	{
		for (int i = 0; i < baseline.getItemCount(); i++)
		{
			if (baseline.getItemAt(i).raid.id.equals(id))
			{
				baseline.setSelectedIndex(i);
				return;
			}
		}
	}

	private void filter()
	{
		String query = search.getText().trim().toLowerCase(Locale.ROOT);
		int size = teamSize.getSelectedIndex();
		filtered = raids.stream().filter(r -> size == 0 || (r.teamSize > 0 ? r.teamSize : r.members.size()) == size)
			.filter(r -> details(r).toLowerCase(Locale.ROOT).contains(query)).collect(Collectors.toList());
		selectionModel.fireTableDataChanged();
	}

	private void rebuildComparison()
	{
		List<TfaRaid> chosen = new ArrayList<>();
		for (String id : selected)
		{
			raids.stream().filter(r -> r.id.equals(id)).findFirst().ifPresent(chosen::add);
		}
		String previous = comparisonModel.baselineId;
		updating = true;
		baseline.removeAllItems();
		for (int i = 0; i < chosen.size(); i++)
		{
			baseline.addItem(new Choice(chosen.get(i), i + 1));
		}
		baseline.setEnabled(!chosen.isEmpty());
		setBaseline(previous == null ? "" : previous);
		Choice choice = (Choice) baseline.getSelectedItem();
		comparisonModel.setRaids(chosen, choice == null ? null : choice.raid.id);
		updating = false;
		count.setText(chosen.size() + " / 5 raids selected" + (chosen.isEmpty() ? " — select raids from the list" : " — differences vs. baseline"));
		for (int i = 0; i < comparison.getColumnCount(); i++)
		{
			comparison.getColumnModel().getColumn(i).setPreferredWidth(i == 0 ? 175 : 235);
		}
		resizeTimingRows();
	}

	private void resizeTimingRows()
	{
		// JTable clears per-row heights on a data change, including a baseline switch.
		for (int row = 0; row < comparison.getRowCount(); row++)
		{
			comparison.setRowHeight(row, row < 3 ? 46 : comparisonModel.isStage(row) ? 78 : 64);
		}
	}

	private static String details(TfaRaid raid)
	{
		int team = raid.teamSize > 0 ? raid.teamSize : raid.members.size();
		return DATE.format(Instant.ofEpochMilli(raid.started)) + " | " + raid.status + " | " + team
			+ " players | " + TfaRaid.time(raid.total) + " | " + String.join(", ", raid.members);
	}

	private static void styleTable(JTable table)
	{
		table.setFont(UI_FONT);
		table.getTableHeader().setFont(new Font(Font.SANS_SERIF, Font.BOLD, 14));
		table.getTableHeader().setPreferredSize(new Dimension(0, 34));
		table.setBackground(CARD);
		table.setForeground(TEXT);
		table.setGridColor(new Color(57, 57, 57));
		table.setSelectionBackground(new Color(65, 65, 65));
		table.setSelectionForeground(TEXT);
		table.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		table.setFillsViewportHeight(true);
	}

	private static JScrollPane scroll(JTable table)
	{
		JScrollPane pane = new JScrollPane(table);
		pane.getViewport().setBackground(CARD);
		pane.setColumnHeaderView(table.getTableHeader());
		return pane;
	}

	private static final class Choice
	{
		private final TfaRaid raid;
		private final int number;

		private Choice(TfaRaid raid, int number)
		{
			this.raid = raid;
			this.number = number;
		}

		@Override
		public String toString()
		{
			return "Raid " + number + " · " + DATE.format(Instant.ofEpochMilli(raid.started));
		}
	}

	private final class SelectionModel extends AbstractTableModel
	{
		public int getRowCount() { return filtered.size(); }
		public int getColumnCount() { return 2; }
		public String getColumnName(int column) { return column == 0 ? "" : "Saved raids"; }
		public Class<?> getColumnClass(int column) { return column == 0 ? Boolean.class : String.class; }

		public Object getValueAt(int row, int column)
		{
			TfaRaid raid = filtered.get(row);
			return column == 0 ? selected.contains(raid.id) : details(raid);
		}

		public boolean isCellEditable(int row, int column)
		{
			return column == 0 && (selected.size() < 5 || selected.contains(filtered.get(row).id));
		}

		public void setValueAt(Object value, int row, int column)
		{
			if (column == 0 && value instanceof Boolean)
			{
				selectRaid(filtered.get(row).id, (Boolean) value);
			}
		}
	}

	static final class ComparisonModel extends AbstractTableModel
	{
		private List<TfaRaid> raids = new ArrayList<>();
		private final List<String> rows = new ArrayList<>();
		private String baselineId;

		void setRaids(List<TfaRaid> selected, String baseline)
		{
			raids = new ArrayList<>(selected);
			baselineId = baseline;
			rows.clear();
			rows.add("Status");
			rows.add("Team size");
			rows.add("Party");
			rows.add("Total raid time");
			for (int stage = 1; stage <= 5; stage++)
			{
				rows.add("Room " + stage);
			}
			rows.add("Combat time");
			rows.add("Between rooms");
			fireTableStructureChanged();
		}

		public int getRowCount() { return rows.size(); }
		public int getColumnCount() { return raids.size() + 1; }
		public String getColumnName(int column)
		{
			return column == 0 ? "Room / metric" : "Raid " + column + " · " + COLUMN_DATE.format(Instant.ofEpochMilli(raids.get(column - 1).started));
		}

		public Object getValueAt(int row, int column)
		{
			if (column == 0)
			{
				return rows.get(row);
			}
			TfaRaid raid = raids.get(column - 1);
			if (row == 0) { return raid.status; }
			if (row == 1) { return Integer.toString(raid.teamSize > 0 ? raid.teamSize : raid.members.size()); }
			if (row == 2) { return raid.members.isEmpty() ? "Roster not captured" : String.join(", ", raid.members); }
			long value = time(raid, rows.get(row));
			return value < 0 ? "—" : TfaRaid.time(value);
		}

		Long delta(int row, int column)
		{
			if (row < 3 || column == 0)
			{
				return null;
			}
			TfaRaid baseline = raids.stream().filter(r -> r.id.equals(baselineId)).findFirst().orElse(null);
			long value = time(raids.get(column - 1), rows.get(row));
			long reference = baseline == null ? -1 : time(baseline, rows.get(row));
			return value < 0 || reference < 0 ? null : value - reference;
		}

		boolean isBaseline(int column)
		{
			return column > 0 && raids.get(column - 1).id.equals(baselineId);
		}

		boolean isStage(int row)
		{
			return rows.get(row).startsWith("Room ");
		}

		String boss(int row, int column)
		{
			if (!isStage(row) || column == 0)
			{
				return "";
			}
			TfaRaid.Split split = stageSplit(raids.get(column - 1), rows.get(row));
			return split == null ? "Not recorded" : TfaRoom.find(split.room).label;
		}

		private static TfaRaid.Split stageSplit(TfaRaid raid, String metric)
		{
			if (!metric.startsWith("Room "))
			{
				return null;
			}
			int stage = Integer.parseInt(metric.substring(5));
			return raid.splits.stream().filter(split ->
			{
				TfaRoom room = TfaRoom.find(split.room);
				return room != null && room.stage == stage;
			}).findFirst().orElse(null);
		}

		private static long time(TfaRaid raid, String metric)
		{
			if (metric.equals("Total raid time"))
			{
				return "Completed".equals(raid.status) ? raid.total : -1;
			}
			if (metric.equals("Combat time"))
			{
				return raid.completeSplits() ? raid.combatTime() : -1;
			}
			if (metric.equals("Between rooms"))
			{
				return raid.completeSplits() && raid.total >= raid.combatTime() ? raid.total - raid.combatTime() : -1;
			}
			TfaRaid.Split split = stageSplit(raid, metric);
			return split == null ? -1 : split.duration;
		}
	}

	private final class TimingRenderer extends JPanel implements javax.swing.table.TableCellRenderer
	{
		private final JLabel value = new JLabel();
		private final JLabel difference = new JLabel();
		private final JLabel boss = new JLabel();

		private TimingRenderer()
		{
			super(new BorderLayout(0, 3));
			setBorder(BorderFactory.createEmptyBorder(6, 12, 6, 12));
			value.putClientProperty("html.disable", Boolean.TRUE);
			value.setFont(TIME_FONT);
			difference.setFont(DELTA_FONT);
			boss.setFont(SMALL_FONT);
			boss.setForeground(MUTED);
			boss.putClientProperty("html.disable", Boolean.TRUE);
			add(boss, BorderLayout.NORTH);
			add(value, BorderLayout.CENTER);
			add(difference, BorderLayout.SOUTH);
		}

		public Component getTableCellRendererComponent(JTable table, Object text, boolean selectedRow, boolean focus, int row, int column)
		{
			setBackground(column > 0 && comparisonModel.isBaseline(column) ? new Color(49, 49, 49) : CARD);
			value.setText(String.valueOf(text));
			value.setFont(column > 0 && row >= 3 ? TIME_FONT : UI_FONT);
			boss.setText(comparisonModel.boss(row, column));
			value.setForeground(TEXT);
			difference.setText("");
			difference.setForeground(MUTED);
			Long delta = comparisonModel.delta(row, column);
			if (row >= 3 && column > 0 && !"—".equals(text))
			{
				if (comparisonModel.isBaseline(column))
				{
					difference.setText("Baseline");
				}
				else if (delta == null)
				{
					difference.setText("No baseline time");
				}
				else
				{
					difference.setText((delta < 0 ? "−" : delta > 0 ? "+" : "±") + TfaRaid.time(Math.abs(delta)));
					difference.setForeground(delta < 0 ? FASTER : delta > 0 ? SLOWER : MUTED);
				}
			}
			setToolTipText(column == 0 ? String.valueOf(text) : details(comparisonModel.raids.get(column - 1)) + " | " + boss.getText() + " | " + text
				+ (difference.getText().isEmpty() ? "" : " | " + difference.getText()));
			setSize(table.getColumnModel().getColumn(column).getWidth(), table.getRowHeight(row));
			doLayout();
			return this;
		}
	}
}

package com.tfasplitstracker;

import java.util.Arrays;

/** Boss identity and its position in the five-stage raid. */
enum TfaRoom
{
	GUARDIAN(1, "Archive Guardian", "Archive Guardian"),
	EZEKIEL(2, "Ezekiel", "Ezekiel"),
	BORK(2, "Bork", "Bork & the Smorks", "Bork and the Smorks"),
	MOIA(3, "Moia", "Moia"),
	DREADNOTH(3, "Dreadnoth the Jellied", "Dreadnoth the Jellied"),
	DAGONHAI(4, "Dagon'hai Trio", "Dagon'hai Elder & monks", "Dagon'hai Elder and monks", "Dagon'hai Elder"),
	XARTH(4, "Xarth", "Xarth"),
	OCELLUS(5, "Ocellus", "Ocellus");

	final int stage;
	final String key;
	final String label;
	private final String[] aliases;

	TfaRoom(int stage, String key, String label, String... aliases)
	{
		this.stage = stage;
		this.key = key;
		this.label = label;
		this.aliases = aliases;
	}

	static TfaRoom find(String name)
	{
		if (name == null)
		{
			return null;
		}
		String normalized = name.replace('\u2019', '\'').trim();
		return Arrays.stream(values()).filter(room -> room.key.equalsIgnoreCase(normalized)
			|| room.label.equalsIgnoreCase(normalized)
			|| Arrays.stream(room.aliases).anyMatch(alias -> alias.equalsIgnoreCase(normalized))).findFirst().orElse(null);
	}
}

package com.tfasplitstracker;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.overlay.infobox.InfoBox;

final class TfaSplitInfoBox extends InfoBox
{
	private final TfaSplitsTrackerPlugin plugin;
	private final TfaSplitsTrackerConfig config;
	private final TfaRaid.Split split;

	TfaSplitInfoBox(TfaSplitsTrackerPlugin plugin, TfaSplitsTrackerConfig config, TfaRaid.Split split)
	{
		super(image(split.room), plugin);
		this.plugin = plugin;
		this.config = config;
		this.split = split;
	}

	@Override public String getText()
	{
		if (config.infoBoxText() == TfaSplitsTrackerConfig.InfoBoxText.NONE) { return ""; }
		long time = config.infoBoxText() == TfaSplitsTrackerConfig.InfoBoxText.CUMULATIVE ? split.cumulative : split.duration;
		String precise = TfaRaid.time(time);
		return time < 0 ? precise : precise.substring(0, precise.indexOf('.'));
	}

	@Override public Color getTextColor() { return Color.GREEN; }
	@Override public boolean render() { return config.showInfoBoxes() && plugin.timingVisible(); }
	@Override public String getTooltip()
	{
		TfaRaid raid = plugin.displayRaid();
		String comparison = raid != null && raid.personalBest != null
			? raid.personalBest.comparison(split) : "";
		return !config.infoBoxTooltip() ? "" : "TFA: " + TfaTiming.label(split.room)
			+ "<br>Room time: " + TfaRaid.time(split.duration)
			+ (config.infoBoxCumulative() ? "<br>Raid split: " + TfaRaid.time(split.cumulative) : "")
			+ (comparison.isEmpty() ? "" : "<br>vs scale " + raid.personalBest.scale + " PB: " + comparison);
	}

	private static BufferedImage image(String room)
	{
		BufferedImage image = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.drawImage(TfaSplitsTrackerPlugin.icon(), 4, 0, null);
		graphics.setColor(Color.WHITE);
		graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
		TfaRoom known = TfaRoom.find(room);
		graphics.drawString(known == null ? "?" : Integer.toString(known.stage), 24, 10);
		graphics.dispose();
		return image;
	}
}

package com.tfasplitstracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

/** Timing-only overlay. PB comparisons belong in the sidebar and optional chat. */
public class TfaSplitsOverlay extends OverlayPanel
{
	private static final Color MUTED = new Color(170, 170, 170);
	private final TfaSplitsTrackerPlugin plugin;
	private final TfaSplitsTrackerConfig config;

	@Inject
	TfaSplitsOverlay(TfaSplitsTrackerPlugin plugin, TfaSplitsTrackerConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(240, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		panelComponent.getChildren().clear();
		TfaRaid raid = plugin.displayRaid();
		if (!config.showOverlay() || raid == null || !plugin.timingVisible()) { return null; }
		line("TFA", config.overlayCumulative() ? "Room / Raid" : "Room time", MUTED);
		for (TfaRaid.Split split : raid.splits)
		{
			line(TfaTiming.label(split.room), split.duration < 0 ? "In progress" : TfaRaid.time(split.duration)
				+ (config.overlayCumulative() ? " / " + TfaRaid.time(split.cumulative) : ""), Color.WHITE);
			if (config.overlayOcellusPhases())
			{
				for (TfaRaid.Phase phase : split.phases)
				{
					boolean active = raid.active() && split.duration < 0 && phase == split.phases.get(split.phases.size() - 1);
					line("  " + TfaOcellus.label(phase.number), phase.duration >= 0 ? TfaRaid.time(phase.duration)
						: active ? "In progress" : "Unrecorded", MUTED);
				}
			}
		}
		long elapsed = raid.active() && plugin.liveState().elapsed >= 0 ? plugin.liveState().elapsed : raid.total;
		line(raid.active() ? "Raid time" : "Raid total", TfaRaid.time(elapsed), Color.WHITE);
		return super.render(graphics);
	}

	private void line(String label, String value, Color color)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(label).right(value).rightColor(color).build());
	}
}

