import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.infobox.InfoBoxManager;

@Slf4j
@PluginDescriptor(
	name = "TFA Splits Tracker",
	description = "Fractured Archive raid history, server room splits, total times and party members",
	tags = {"tfa", "fractured", "archive", "raid", "splits", "timer", "party"},
	enabledByDefault = true
)
public class TfaSplitsTrackerPlugin extends Plugin
{
	private static final String GROUP = TfaSplitsTrackerConfig.GROUP;
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ClientToolbar toolbar;
	@Inject private ConfigManager configManager;
	@Inject private Gson gson;
	@Inject private TfaSplitsTrackerConfig config;
	@Inject private ChatMessageManager chatMessageManager;
	@Inject private InfoBoxManager infoBoxManager;
	@Inject private OverlayManager overlayManager;
	@Inject private TfaSplitsOverlay overlay;
	private TfaOcellus ocellus = new TfaOcellus();
	private TfaTracker tracker = new TfaTracker();
	private TfaSplitsTrackerPanel panel;
	private NavigationButton navigation;
	private volatile boolean running;
	private boolean storageHealthy = true;
	private volatile boolean liveAvailable;
	private volatile TfaRaid displayRaid;
	private volatile TfaLiveState liveState = TfaLiveState.UNAVAILABLE;
	private boolean raidSessionActive;
	private boolean awaitingRaidStart;

	@Provides
	TfaSplitsTrackerConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(TfaSplitsTrackerConfig.class);
	}

	@Override
	protected void startUp()
	{
		running = true;
		overlayManager.add(overlay);
		panel = new TfaSplitsTrackerPanel(this::delete, this::undoDelete);
		navigation = NavigationButton.builder().tooltip("TFA Splits Tracker").icon(icon()).priority(7).panel(panel).build();
		toolbar.addNavigation(navigation);
		clientThread.invokeLater(() ->
		{
			if (running)
			{
				load();
				reconcile(false);
				refreshRaidState();
				publish();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		running = false;
		overlayManager.remove(overlay);
		ocellus = new TfaOcellus();
		infoBoxManager.removeIf(box -> box instanceof TfaSplitInfoBox);
		displayRaid = null;
		liveState = TfaLiveState.UNAVAILABLE;
		raidSessionActive = false;
		awaitingRaidStart = false;
		toolbar.removeNavigation(navigation);
		panel.stop();
		// Every accepted timing and roster update has already been persisted.
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		clientThread.invokeLater(() ->
		{
			if (running)
			{
				load();
				reconcile(false);
				refreshRaidState();
				publish();
			}
		});
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		onProfileChanged(new ProfileChanged());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (running && configManager.getRSProfileKey() != null && event.getType() == ChatMessageType.GAMEMESSAGE)
		{
			// Reconcile older messages first, including when a callback was not delivered.
			reconcile(true);
			boolean changed = accept(event.getMessage(), event.getTimestamp() * 1000L, true);
			TfaRaid.Split room = liveOcellus();
			if (room != null && room.started == event.getTimestamp() * 1000L
				&& "Challenge started: Ocellus.".equals(TfaLiveState.clean(event.getMessage())))
			{
				int previous = room.phases.size();
				ocellus.begin(room, client.getTickCount());
				changed |= room.phases.size() != previous;
			}
			if (changed)
			{
				captureParty();
				saveAndPublish();
			}
		}
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event) { observeOcellus(event.getNpc(), false, true); }

	@Subscribe
	public void onNpcSpawned(NpcSpawned event) { observeOcellus(event.getNpc(), false, false); }

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() instanceof NPC && event.getActor().getAnimation() == TfaOcellus.DESTROY_QUADRANT_ANIMATION)
		{
			observeOcellus((NPC) event.getActor(), true, true);
		}
	}

	private void observeOcellus(NPC npc, boolean quadrantDestroyed, boolean boundary)
	{
		if (!running || configManager.getRSProfileKey() == null || client.getGameState() != GameState.LOGGED_IN
			|| npc.getWorldView() != client.getTopLevelWorldView()
			|| npc.getId() != TfaOcellus.VINES_NPC && npc.getId() != TfaOcellus.PORTALS_NPC
				&& npc.getId() != TfaOcellus.QUADRANTS_NPC) { return; }
		reconcile(true);
		TfaRaid.Split room = liveOcellus();
		if (room == null) { return; }
		TfaRaid before = tracker.current().copy();
		boolean changed = quadrantDestroyed
			? npc.getId() == TfaOcellus.QUADRANTS_NPC && ocellus.destroyQuadrant(room, client.getTickCount())
			: ocellus.observe(room, npc.getId(), client.getTickCount(), boundary);
		if (changed)
		{
			announce(before);
			saveAndPublish();
		}
	}

	private TfaRaid.Split liveOcellus()
	{
		TfaRaid raid = tracker.current();
		if (raid == null || raid.splits.isEmpty()) { return null; }
		TfaRaid.Split last = raid.splits.get(raid.splits.size() - 1);
		return "Ocellus".equals(last.room) && last.duration < 0 ? last : null;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (running)
		{
			reconcile(true);
			refreshRaidState();
			if (captureParty())
			{
				saveAndPublish();
			}
			if (liveAvailable != raidHudVisible())
			{
				publish();
			}
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (!running) { return; }
		updateLiveState(readLiveState());
	}

	private void updateLiveState(TfaLiveState state)
	{
		boolean enteredRaid = state.inRaid && !raidSessionActive;
		if (enteredRaid)
		{
			raidSessionActive = true;
			awaitingRaidStart = tracker.current() == null;
		}
		WorldView world = client.getTopLevelWorldView();
		if (client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null
			&& world != null && !world.isInstance())
		{
			raidSessionActive = false;
			awaitingRaidStart = false;
		}
		TfaLiveState previous = liveState;
		if (state.inRaid == previous.inRaid && state.elapsed == previous.elapsed && state.status.equals(previous.status)) { return; }
		liveState = state;
		if (enteredRaid)
		{
			// A new instance starts with no splits, before the first challenge chat arrives.
			publish();
		}
		TfaSplitsTrackerPanel target = panel;
		SwingUtilities.invokeLater(() ->
		{
			if (running && panel == target) { target.updateLiveState(state); }
		});
	}

	private TfaLiveState readLiveState()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return client.getGameState() == GameState.LOADING && raidSessionActive
				? new TfaLiveState(true, "Loading raid", -1) : TfaLiveState.UNAVAILABLE;
		}
		boolean hudVisible = raidHudVisible();
		WorldView world = client.getTopLevelWorldView();
		// The game hides the HUD between encounters; the instance/session outlives it.
		boolean inRaid = world != null && world.isInstance()
			&& (hudVisible || raidSessionActive || tracker.current() != null);
		Widget status = client.getWidget(inRaid ? InterfaceID.TfaHud.RAID_STATE : InterfaceID.TfaHud.STATUS);
		Widget clock = client.getWidget(InterfaceID.TfaHud.RAID_TIMER);
		String text = !hudVisible || status == null || status.isHidden() ? "" : TfaLiveState.clean(status.getText());
		if (inRaid && !hudVisible)
		{
			TfaRaid raid = tracker.current();
			TfaRaid.Split last = raid == null || raid.splits.isEmpty() ? null : raid.splits.get(raid.splits.size() - 1);
			text = last != null && last.duration >= 0 ? "Between rooms" : "Raid HUD unavailable";
		}
		return new TfaLiveState(inRaid, text,
			!inRaid || !hudVisible || clock == null || clock.isHidden() ? -1 : TfaLiveState.parseClock(clock.getText()));
	}

	private void refreshRaidState()
	{
		updateLiveState(readLiveState());
		// Loading, reconnecting and temporary HUD loss are not evidence of leaving.
		WorldView world = client.getTopLevelWorldView();
		if (client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null
			&& world != null && !world.isInstance() && tracker.leaveRaid())
		{
			saveAndPublish();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (running)
		{
			publish();
		}
	}

	@Subscribe
	public void onVarClientStrChanged(VarClientStrChanged event)
	{
		if (running && event.getIndex() >= VarClientID.TFA_CLIENT_NAME0 && event.getIndex() <= VarClientID.TFA_CLIENT_NAME7)
		{
			// The game refreshes all eight slots in one script; wait for that refresh to finish.
			clientThread.invokeLater(() ->
			{
				if (running && captureParty())
				{
					saveAndPublish();
				}
			});
		}
	}

	private void reconcile(boolean announce)
	{
		if (configManager.getRSProfileKey() == null || client.getGameState() != GameState.LOGGED_IN || client.getMessages() == null)
		{
			return;
		}
		List<MessageNode> messages = new ArrayList<>();
		for (MessageNode node : client.getMessages())
		{
			if (node.getType() == ChatMessageType.GAMEMESSAGE && node.getTimestamp() * 1000L >= tracker.lastEvent)
			{
				messages.add(node);
			}
		}
		messages.sort(Comparator.comparingInt(MessageNode::getTimestamp).thenComparingInt(MessageNode::getId));
		boolean changed = false;
		for (MessageNode node : messages)
		{
			changed |= accept(node.getValue(), node.getTimestamp() * 1000L, announce);
		}
		if (changed)
		{
			captureParty();
			saveAndPublish();
		}
	}

	private boolean accept(String message, long timestamp, boolean announce)
	{
		TfaRaid before = tracker.raids.isEmpty() ? null : tracker.raids.get(0).copy();
		if (!tracker.accept(message, timestamp)) { return false; }
		TfaRaid latest = tracker.raids.isEmpty() ? null : tracker.raids.get(0);
		if (latest != null && (latest.active() || before == null || !before.id.equals(latest.id)))
		{
			awaitingRaidStart = false;
		}
		if (announce)
		{
			announce(before);
		}
		return true;
	}

	private void announce(TfaRaid before)
	{
		TfaRaid after = tracker.raids.isEmpty() ? null : tracker.raids.get(0);
		for (String text : TfaTiming.messages(before, after, config))
		{
			chatMessageManager.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(text).build());
		}
	}

	TfaRaid displayRaid() { return displayRaid; }
	TfaLiveState liveState() { return liveState; }

	boolean timingVisible()
	{
		return running && client.getGameState() == GameState.LOGGED_IN && liveState.inRaid;
	}

	private boolean captureParty()
	{
		WorldView world = client.getTopLevelWorldView();
		if (tracker.current() == null || world == null || !world.isInstance() || !raidHudVisible())
		{
			return false;
		}
		List<String> names = new ArrayList<>();
		for (int slot = VarClientID.TFA_CLIENT_NAME0; slot <= VarClientID.TFA_CLIENT_NAME7; slot++)
		{
			names.add(client.getVarcStrValue(slot));
		}
		return tracker.party(names);
	}

	private boolean raidHudVisible()
	{
		Widget hud = client.getWidget(InterfaceID.TfaHud.UNIVERSE);
		return client.getGameState() == GameState.LOGGED_IN && hud != null && !hud.isHidden();
	}

	private void load()
	{
		ocellus = new TfaOcellus();
		tracker = new TfaTracker();
		storageHealthy = true;
		try
		{
			String json = configManager.getRSProfileConfiguration(GROUP, "history");
			if (json != null)
			{
				TfaTracker saved = gson.fromJson(json, TfaTracker.class);
				if (saved != null)
				{
					tracker = saved;
				}
			}
		}
		catch (RuntimeException ex)
		{
			storageHealthy = false;
			log.warn("Unable to read TFA splits history; preserving the stored data", ex);
		}
	}

	private void saveAndPublish()
	{
		if (storageHealthy && configManager.getRSProfileKey() != null)
		{
			configManager.setRSProfileConfiguration(GROUP, "history", gson.toJson(tracker));
		}
		publish();
	}

	private void delete(String raidId, String room)
	{
		String profile = configManager.getRSProfileKey();
		clientThread.invokeLater(() ->
		{
			if (running && profile != null && profile.equals(configManager.getRSProfileKey()) && tracker.delete(raidId, room))
			{
				saveAndPublish();
			}
		});
	}

	private void undoDelete()
	{
		String profile = configManager.getRSProfileKey();
		clientThread.invokeLater(() ->
		{
			if (running && profile != null && profile.equals(configManager.getRSProfileKey()) && tracker.undoDelete())
			{
				saveAndPublish();
			}
		});
	}

	private void publish()
	{
		// Swing receives its own immutable-in-practice copy; the game thread owns the reducer.
		TfaTracker snapshot = gson.fromJson(gson.toJson(tracker), TfaTracker.class);
		displayRaid = awaitingRaidStart || snapshot.raids.isEmpty() ? null : snapshot.raids.get(0);
		infoBoxManager.removeIf(box -> box instanceof TfaSplitInfoBox);
		if (displayRaid != null)
		{
			for (TfaRaid.Split split : displayRaid.splits)
			{
				if (split.duration >= 0) { infoBoxManager.addInfoBox(new TfaSplitInfoBox(this, config, split)); }
			}
		}
		TfaSplitsTrackerPanel target = panel;
		boolean healthy = storageHealthy;
		liveAvailable = raidHudVisible();
		TfaLiveState state = liveState;
		SwingUtilities.invokeLater(() ->
		{
			if (running && panel == target)
			{
				target.update(snapshot, healthy, state);
			}
		});
	}

	static BufferedImage icon()
	{
		BufferedImage image = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(99, 218, 204));
		g.setStroke(new BasicStroke(2));
		g.drawOval(4, 5, 16, 16);
		g.drawLine(12, 8, 12, 13);
		g.drawLine(12, 13, 16, 15);
		g.drawLine(9, 2, 15, 2);
		g.drawLine(12, 2, 12, 5);
		g.dispose();
		return image;
	}
}

package com.tfasplitstracker;

import java.util.ArrayList;
import java.util.List;

/** Room server times and observed phase times for the local chatbox. */
final class TfaTiming
{
	private TfaTiming() { }

	static String label(String room)
	{
		TfaRoom known = TfaRoom.find(room);
		return known == null ? room : known.label;
	}

	static List<String> messages(TfaRaid before, TfaRaid after, TfaSplitsTrackerConfig config)
	{
		List<String> messages = new ArrayList<>();
		if (after == null) { return messages; }
		boolean sameRaid = before != null && before.id.equals(after.id);
		if (config.chatOcellusPhases())
		{
			for (TfaRaid.Split split : after.splits)
			{
				for (TfaRaid.Phase phase : split.phases)
				{
					boolean recorded = sameRaid && before.splits.stream().filter(s -> s.room.equals(split.room))
						.flatMap(s -> s.phases.stream()).anyMatch(p -> p.number == phase.number && p.duration >= 0);
					if (phase.duration < 0 || recorded) { continue; }
					TfaRaid.Phase reference = config.chatPersonalBest() && after.personalBest != null
						? after.personalBest.phase(split, phase.number) : null;
					messages.add("TFA: Ocellus " + TfaOcellus.label(phase.number) + " - " + TfaRaid.time(phase.duration)
						+ (reference == null ? "" : " | vs scale " + after.personalBest.scale + " PB: "
							+ TfaPersonalBest.delta(phase.duration - reference.duration)));
				}
			}
		}
		if (config.chatSplits())
		{
			for (TfaRaid.Split split : after.splits)
			{
				boolean alreadyCompleted = sameRaid && before.splits.stream()
					.anyMatch(old -> old.room.equals(split.room) && old.duration >= 0);
				if (split.duration >= 0 && !alreadyCompleted)
				{
					String comparison = config.chatPersonalBest() && after.personalBest != null
						? after.personalBest.comparison(split) : "";
					messages.add("TFA: " + label(split.room) + " - " + TfaRaid.time(split.duration)
						+ " (raid split " + TfaRaid.time(split.cumulative) + ")"
						+ (comparison.isEmpty() ? "" : " | vs scale " + after.personalBest.scale + " PB: " + comparison));
				}
			}
		}
		if (config.chatTotal() && "Completed".equals(after.status)
			&& (!sameRaid || !"Completed".equals(before.status)))
		{
			messages.add("TFA: Raid complete - " + TfaRaid.time(after.total)
				+ (config.chatPersonalBest() && after.personalBest != null
					? " | vs scale " + after.personalBest.scale + " PB: " + TfaPersonalBest.delta(after.total - after.personalBest.total) : ""));
		}
		return messages;
	}
}

package com.tfasplitstracker;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Event reducer shared by live chat, chat-buffer recovery, and recorded-log tests. */
final class TfaTracker
{
	private static final String TIME = "(\\d+:\\d{2}(?::\\d{2})?(?:\\.\\d{1,3})?)";
	private static final Pattern START = Pattern.compile("^Challenge started: (.+)\\.$");
	private static final Pattern SPLIT = Pattern.compile("^Challenge complete: (.+)\\. Duration: " + TIME + "\\. Total: " + TIME + ".*$");
	private static final Pattern TOTAL = Pattern.compile("^The Fractured Archive: Total completion time: " + TIME + ".*$");
	private static final Pattern READY = Pattern.compile("^\\d+/([1-8]) party members are now ready\\.$");
	final List<TfaRaid> raids = new ArrayList<>();
	// Persist the event journal as well as the records, so re-enabling cannot replay old starts.
	final Set<String> processed = new LinkedHashSet<>();
	long lastEvent;
	TfaRaid deleted;
	int deletedIndex;
	boolean suppressUntilNextRaid;

	boolean delete(String raidId, String room)
	{
		for (int i = 0; i < raids.size(); i++)
		{
			TfaRaid raid = raids.get(i);
			if (!raid.id.equals(raidId) || room != null && raid.active())
			{
				continue;
			}
			if (room != null && raid.splits.stream().noneMatch(s -> s.room.equals(room)))
			{
				return false;
			}
			if (raid.active())
			{
				suppressUntilNextRaid = true;
			}
			else
			{
				deleted = raid.copy();
				deletedIndex = i;
			}
			if (room == null)
			{
				raids.remove(i);
			}
			else
			{
				raid.splits.removeIf(s -> s.room.equals(room));
			}
			// Keep the event journal: retained chat must not resurrect a deleted record.
			return true;
		}
		return false;
	}

	boolean undoDelete()
	{
		if (deleted == null)
		{
			return false;
		}
		raids.removeIf(r -> r.id.equals(deleted.id));
		// A newly started raid must remain first so current() can find it.
		int firstSaved = current() == null ? 0 : 1;
		raids.add(Math.min(raids.size(), Math.max(firstSaved, deletedIndex)), deleted);
		deleted = null;
		while (raids.size() > 200)
		{
			raids.remove(raids.size() - 1);
		}
		return true;
	}

	TfaRaid current()
	{
		return !raids.isEmpty() && raids.get(0).active() ? raids.get(0) : null;
	}

	boolean leaveRaid()
	{
		TfaRaid raid = current();
		if (raid == null) { return false; }
		// Preserve server timings and the event journal; leaving is not a completed split.
		raid.status = "Left raid";
		return true;
	}

	boolean accept(String raw, long timestamp)
	{
		if (raw == null)
		{
			return false;
		}
		String message = raw.replaceAll("<[^>]*>", "").replace('\u00a0', ' ').trim();
		Matcher start = START.matcher(message);
		Matcher split = SPLIT.matcher(message);
		Matcher total = TOTAL.matcher(message);
		Matcher ready = READY.matcher(message);
		TfaRoom startRoom = start.matches() ? TfaRoom.find(start.group(1)) : null;
		TfaRoom completedRoom = split.matches() ? TfaRoom.find(split.group(1)) : null;
		boolean isStart = startRoom != null;
		boolean isSplit = completedRoom != null;
		boolean isTotal = total.matches();
		boolean isReady = ready.matches() && current() != null;
		boolean failed = message.equals("You failed to survive the Fractured Archive.");
		boolean abandoned = message.equals("You abandon the raid and leave the Fractured Archive.");
		if (!isStart && !isSplit && !isTotal && !isReady && !failed && !abandoned)
		{
			return false;
		}
		String key = timestamp + ":" + message;
		if (processed.contains(key) || timestamp < lastEvent)
		{
			return false;
		}
		processed.add(key);
		while (processed.size() > 4096)
		{
			processed.remove(processed.iterator().next());
		}
		lastEvent = timestamp;
		if (suppressUntilNextRaid)
		{
			if (isStart && startRoom == TfaRoom.GUARDIAN)
			{
				suppressUntilNextRaid = false;
			}
			else
			{
				return true;
			}
		}
		if (isStart)
		{
			String room = startRoom.key;
			TfaRaid raid = current();
			TfaRaid.Split previous = raid == null || raid.splits.isEmpty() ? null : raid.splits.get(raid.splits.size() - 1);
			if (previous != null && room.equals(previous.room) && previous.duration < 0 && previous.started == timestamp)
			{
				return true;
			}
			if (raid != null && room.equals("Archive Guardian"))
			{
				raid.status = "Interrupted";
				raid = null;
			}
			if (raid == null)
			{
				raid = create(timestamp);
			}
			TfaRaid.Split next = new TfaRaid.Split();
			next.room = room;
			next.started = timestamp;
			raid.splits.add(next);
			raid.updated = timestamp;
		}
		else if (isSplit)
		{
			String room = completedRoom.key;
			long duration = parseTime(split.group(2));
			long cumulative = parseTime(split.group(3));
			TfaRaid raid = current();
			if (raid != null && room.equals("Archive Guardian")
				&& raid.splits.stream().anyMatch(s -> s.room.equals(room) && s.duration >= 0))
			{
				// The next run's first completion also recovers a missed first-room start.
				raid.status = "Interrupted";
				raid = null;
			}
			if (raid == null)
			{
				// Ocellus and the overall message are separate signals for the same finish.
				TfaRaid last = raids.isEmpty() ? null : raids.get(0);
				if (last != null && "Completed".equals(last.status) && Math.abs(timestamp - last.updated) <= 2000)
				{
					raid = last;
				}
				else
				{
					raid = create(timestamp - cumulative);
				}
			}
			TfaRaid.Split result = raid.splits.stream().filter(s -> s.room.equals(room)).findFirst().orElse(null);
			if (result == null)
			{
				result = new TfaRaid.Split();
				result.room = room;
				result.started = timestamp - duration;
				raid.splits.add(result);
			}
			result.duration = duration;
			result.cumulative = cumulative;
			raid.total = cumulative;
			raid.updated = timestamp;
			if (room.equals("Ocellus"))
			{
				TfaOcellus.finish(result);
				raid.status = "Completed";
			}
		}
		else if (isTotal)
		{
			TfaRaid raid = current();
			if (raid == null && !raids.isEmpty() && "Completed".equals(raids.get(0).status)
				&& Math.abs(timestamp - raids.get(0).updated) <= 2000)
			{
				raid = raids.get(0);
			}
			long duration = parseTime(total.group(1));
			if (raid == null)
			{
				raid = create(timestamp - duration);
			}
			raid.total = duration;
			raid.updated = timestamp;
			raid.status = "Completed";
		}
		else if (current() != null)
		{
			TfaRaid raid = current();
			if (isReady)
			{
				raid.teamSize = Integer.parseInt(ready.group(1));
			}
			else
			{
				raid.status = failed ? "Failed" : "Abandoned";
				raid.updated = timestamp;
			}
		}
		if (!raids.isEmpty()) { TfaPersonalBest.select(raids.get(0), raids); }
		return true;
	}

	private TfaRaid create(long timestamp)
	{
		TfaRaid raid = new TfaRaid();
		raid.started = timestamp;
		raid.updated = timestamp;
		raids.add(0, raid);
		while (raids.size() > 200)
		{
			raids.remove(raids.size() - 1);
		}
		return raid;
	}

	boolean party(List<String> names)
	{
		TfaRaid raid = current();
		if (raid == null || names.isEmpty())
		{
			return false;
		}
		boolean changed = false;
		Set<String> visible = new java.util.TreeSet<>(String.CASE_INSENSITIVE_ORDER);
		for (String raw : names)
		{
			String name = raw == null ? "" : raw.replaceAll("<[^>]*>", "").replace('\u00a0', ' ').trim();
			if (!name.isEmpty()) { visible.add(name); }
			if (!name.isEmpty() && raid.members.stream().noneMatch(n -> n.equalsIgnoreCase(name)))
			{
				raid.members.add(name);
				changed = true;
			}
		}
		// A partial refresh or a departing member must not shrink the raid's scale.
		if (visible.size() > raid.observedTeamSize)
		{
			raid.observedTeamSize = visible.size();
			TfaPersonalBest.select(raid, raids);
			changed = true;
		}
		return changed;
	}

	static long parseTime(String value)
	{
		String[] parts = value.split(":");
		long seconds = 0;
		for (int i = 0; i < parts.length - 1; i++)
		{
			seconds = (seconds + Long.parseLong(parts[i])) * 60;
		}
		return seconds * 1000 + new java.math.BigDecimal(parts[parts.length - 1]).movePointRight(3).longValueExact();
	}
}

package com.tfasplitstracker;

import com.google.gson.Gson;
import org.junit.Test;
import static org.junit.Assert.*;

public class TfaOcellusTest
{
	static TfaTracker completedFight()
	{
		TfaTracker tracker = new TfaTracker();
		tracker.accept("Challenge started: Ocellus.", 100000);
		TfaRaid.Split split = tracker.current().splits.get(0);
		TfaOcellus phases = new TfaOcellus();
		phases.begin(split, 100);
		phases.begin(split, 101); // Duplicate callback must not move the start.
		assertTrue(phases.observe(split, 16675, 200, true));
		assertFalse(phases.observe(split, 16675, 201, true));
		assertTrue(phases.observe(split, 16677, 300, true));
		assertFalse(phases.destroyQuadrant(split, 340));
		assertFalse(phases.destroyQuadrant(split, 340));
		assertFalse(phases.destroyQuadrant(split, 370));
		assertTrue(phases.destroyQuadrant(split, 400));
		assertFalse(phases.destroyQuadrant(split, 400));
		tracker.accept("Challenge complete: Ocellus. Duration: 3:30.00. Total: 9:00.00", 310000);
		return tracker;
	}

	@Test
	public void recordsFourPhasesAndUsesServerDurationForFinalRemainder()
	{
		TfaTracker tracker = completedFight();
		TfaRaid.Split split = tracker.raids.get(0).splits.get(0);
		assertEquals(4, split.phases.size());
		assertArrayEquals(new long[] {60000, 60000, 60000, 30000}, split.phases.stream().mapToLong(p -> p.duration).toArray());
		assertEquals(split.duration, split.phases.stream().mapToLong(p -> p.duration).sum());
		assertEquals(180000, split.phases.get(2).cumulative);
		TfaRaid copy = tracker.raids.get(0).copy();
		copy.splits.get(0).phases.get(0).duration = 1;
		assertEquals(60000, split.phases.get(0).duration);
		TfaTracker loaded = new Gson().fromJson(new Gson().toJson(tracker), TfaTracker.class);
		assertEquals(30000, loaded.raids.get(0).splits.get(0).phases.get(3).duration);
	}

	@Test
	public void lateNpcSpawnAndReloadDoNotInventMissingPhaseTimes()
	{
		TfaRaid.Split split = new TfaRaid.Split();
		TfaOcellus phases = new TfaOcellus();
		phases.observe(split, 16675, 100, false); // Joining an already-running portal phase.
		phases.observe(split, 16677, 200, true);
		assertEquals(-1, split.phases.get(0).duration);
		assertEquals(-1, split.phases.get(1).duration);
		phases = new TfaOcellus(); // Re-enable halfway through quadrants.
		phases.observe(split, 16677, 250, false);
		phases.destroyQuadrant(split, 300);
		phases.destroyQuadrant(split, 350);
		phases.destroyQuadrant(split, 400);
		split.duration = 210000;
		TfaOcellus.finish(split);
		assertTrue(split.phases.stream().allMatch(p -> p.duration < 0));
		TfaRaid old = new Gson().fromJson("{\"splits\":[{\"room\":\"Ocellus\",\"duration\":1000}]}", TfaRaid.class);
		assertTrue(old.copy().splits.get(0).phases.isEmpty());
	}

	@Test
	public void p1SpawnBeforeLiveStartCallbackStillGetsFullTiming()
	{
		TfaRaid.Split split = new TfaRaid.Split();
		TfaOcellus phases = new TfaOcellus();
