public class TfaSplitsTrackerPluginTest
{
	private static void inject(Object target, String name, Object value) throws Exception
	{
		Field field = target.getClass().getDeclaredField(name);
		field.setAccessible(true);
		field.set(target, value);
	}

	@Test
	@SuppressWarnings("unchecked")
	public void gameTickRecoversMissedChatCallbackAndCapturesAuthoritativeParty() throws Exception
	{
		TfaSplitsTrackerPlugin plugin = new TfaSplitsTrackerPlugin();
		Client client = mock(Client.class);
		ClientThread thread = mock(ClientThread.class);
		ConfigManager config = mock(ConfigManager.class);
		when(config.getRSProfileKey()).thenReturn("test-profile");
		inject(plugin, "client", client);
		inject(plugin, "clientThread", thread);
		inject(plugin, "toolbar", mock(ClientToolbar.class));
		inject(plugin, "configManager", config);
		inject(plugin, "gson", new Gson());
		ChatMessageManager chat = mock(ChatMessageManager.class);
		InfoBoxManager boxes = mock(InfoBoxManager.class);
		TfaSplitsTrackerConfig settings = new TfaSplitsTrackerConfig() { };
		inject(plugin, "config", settings);
		inject(plugin, "chatMessageManager", chat);
		inject(plugin, "infoBoxManager", boxes);
		OverlayManager overlays = mock(OverlayManager.class);
		TfaSplitsOverlay overlay = new TfaSplitsOverlay(plugin, settings);
		inject(plugin, "overlayManager", overlays);
		inject(plugin, "overlay", overlay);
		doAnswer(invocation ->
		{
			((Runnable) invocation.getArgument(0)).run();
			return null;
		}).when(thread).invokeLater(any(Runnable.class));
		when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
		net.runelite.api.WorldView world = mock(net.runelite.api.WorldView.class);
		when(client.getTopLevelWorldView()).thenReturn(world);
		when(world.isInstance()).thenReturn(true);
		when(client.getLocalPlayer()).thenReturn(mock(net.runelite.api.Player.class));
		Widget hud = mock(Widget.class);
		when(client.getWidget(InterfaceID.TfaHud.UNIVERSE)).thenReturn(hud);
		Widget clock = mock(Widget.class);
		when(client.getWidget(InterfaceID.TfaHud.RAID_TIMER)).thenReturn(clock);
		when(clock.getText()).thenReturn("<col=ffffff>1:23.40</col>");
		when(client.getVarcStrValue(VarClientID.TFA_CLIENT_NAME0)).thenReturn("First\u00a0Raider");
		when(client.getVarcStrValue(VarClientID.TFA_CLIENT_NAME7)).thenReturn("Eighth Raider");
		IterableHashTable<MessageNode> table = mock(IterableHashTable.class);
		List<MessageNode> messages = new ArrayList<>();
		when(table.iterator()).thenAnswer(invocation -> messages.iterator());
		when(client.getMessages()).thenReturn(table);
		SwingUtilities.invokeAndWait(plugin::startUp);
		try
		{
			MessageNode start = mock(MessageNode.class);
			when(start.getType()).thenReturn(ChatMessageType.GAMEMESSAGE);
			when(start.getTimestamp()).thenReturn(100);
			when(start.getValue()).thenReturn("Challenge started: Archive Guardian.");
			messages.add(start);
			plugin.onGameTick(new GameTick()); // No ChatMessage callback was delivered.
			Field field = TfaSplitsTrackerPlugin.class.getDeclaredField("tracker");
			field.setAccessible(true);
			TfaTracker tracker = (TfaTracker) field.get(plugin);
			assertNotNull(tracker.current());
			assertEquals(2, tracker.current().members.size());
			assertTrue(tracker.current().members.contains("First Raider"));
			assertTrue(tracker.current().members.contains("Eighth Raider"));
			assertEquals(2, tracker.current().scale());
			assertEquals("No recorded PB for scale 2", TfaPersonalBest.status(plugin.displayRaid()));
			plugin.onGameTick(new GameTick());
			assertEquals(1, tracker.current().splits.size());
			assertEquals(83400, plugin.liveState().elapsed);
			when(clock.getText()).thenReturn("1:24.60");
			plugin.onClientTick(new ClientTick());
			assertEquals(84600, plugin.liveState().elapsed);
			when(client.getGameState()).thenReturn(GameState.LOADING);
			plugin.onGameTick(new GameTick());
			assertNotNull(tracker.current());
			assertTrue(plugin.liveState().inRaid);
			when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
			when(hud.isHidden()).thenReturn(true);
			when(client.getVarcStrValue(VarClientID.TFA_CLIENT_NAME7)).thenReturn("Stale Lobby Name");
			plugin.onVarClientStrChanged(new VarClientStrChanged(VarClientID.TFA_CLIENT_NAME7));
			assertFalse(tracker.current().members.contains("Stale Lobby Name"));
			verify(config, atLeastOnce()).setRSProfileConfiguration(eq("tfasplitstracker"), eq("history"), any());
			MessageNode complete = mock(MessageNode.class);
			when(complete.getType()).thenReturn(ChatMessageType.GAMEMESSAGE);
			when(complete.getTimestamp()).thenReturn(160);
			when(complete.getValue()).thenReturn("Challenge complete: Archive Guardian. Duration: 1:00.00. Total: 1:00.00");
			messages.add(complete);
			plugin.onGameTick(new GameTick());
			ChatMessage callback = new ChatMessage();
			callback.setType(ChatMessageType.GAMEMESSAGE);
			callback.setTimestamp(160);
			callback.setMessage(complete.getValue());
			plugin.onChatMessage(callback);
			plugin.onGameTick(new GameTick());
			verify(chat, times(1)).queue(any(QueuedMessage.class));
			assertEquals(60000, plugin.displayRaid().splits.get(0).duration);
			assertTrue(plugin.liveState().inRaid);
			assertEquals("Between rooms", plugin.liveState().status);
			assertEquals(-1, plugin.liveState().elapsed);
			assertTrue(plugin.timingVisible());
			// Returning HUD and the next room continue the same record.
			String raidId = plugin.displayRaid().id;
			when(hud.isHidden()).thenReturn(false);
			plugin.onClientTick(new ClientTick());
			assertEquals(84600, plugin.liveState().elapsed);
			callback.setTimestamp(170);
			callback.setMessage("Challenge started: Moia.");
			plugin.onChatMessage(callback);
			assertEquals(raidId, plugin.displayRaid().id);
			assertEquals(2, plugin.displayRaid().splits.size());
			assertEquals(60000, plugin.displayRaid().splits.get(0).duration);
			verify(boxes, atLeastOnce()).addInfoBox(any(TfaSplitInfoBox.class));
			// Reloading the profile recovers retained chat without printing old results.
			plugin.onProfileChanged(new net.runelite.client.events.ProfileChanged());
			verify(chat, times(1)).queue(any(QueuedMessage.class));
			// The party HUD stays open in the public lobby: it is not an active raid.
			when(hud.isHidden()).thenReturn(false);
			when(world.isInstance()).thenReturn(false);
			Widget status = mock(Widget.class);
			when(status.getText()).thenReturn("No Party");
			when(client.getWidget(InterfaceID.TfaHud.STATUS)).thenReturn(status);
			plugin.onGameTick(new GameTick());
			assertFalse(plugin.liveState().inRaid);
			assertEquals("No Party", plugin.liveState().status);
			assertFalse(plugin.timingVisible());
			assertEquals("Left raid", plugin.displayRaid().status);
			assertEquals(60000, plugin.displayRaid().splits.get(0).duration);
			plugin.onGameTick(new GameTick());
			assertEquals("Left raid", plugin.displayRaid().status);
			// Entering the next instance clears old splits before Guardian starts.
			tracker = (TfaTracker) field.get(plugin);
			clearInvocations(boxes);
			when(world.isInstance()).thenReturn(true);
			when(clock.getText()).thenReturn("0:00.00");
			plugin.onClientTick(new ClientTick());
			assertTrue(plugin.liveState().inRaid);
			assertNull(plugin.displayRaid());
			verify(boxes).removeIf(any());
			verify(boxes, never()).addInfoBox(any());
			plugin.onGameTick(new GameTick());
			assertNull(plugin.displayRaid());
			assertEquals("Left raid", tracker.raids.get(0).status);
			assertEquals(60000, tracker.raids.get(0).splits.get(0).duration);
			callback.setTimestamp(200);
			callback.setMessage("Challenge started: Archive Guardian.");
			plugin.onChatMessage(callback);
			assertNotNull(plugin.displayRaid());
			assertTrue(plugin.displayRaid().active());
			assertEquals(1, plugin.displayRaid().splits.size());
			assertEquals(-1, plugin.displayRaid().splits.get(0).duration);
			assertEquals(-1, plugin.displayRaid().total);
			// Temporary loading must not treat a continuing run as a new raid.
			callback.setTimestamp(260);
			callback.setMessage(complete.getValue());
			plugin.onChatMessage(callback);
			when(client.getGameState()).thenReturn(GameState.LOADING);
			plugin.onClientTick(new ClientTick());
			when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
			plugin.onClientTick(new ClientTick());
			assertEquals(60000, plugin.displayRaid().splits.get(0).duration);
			callback.setTimestamp(300);
			callback.setMessage("The Fractured Archive: Total completion time: 1:40.00");
			plugin.onChatMessage(callback);
			assertEquals("Completed", plugin.displayRaid().status);
			// Loading after completion also preserves this session's results.
			when(client.getGameState()).thenReturn(GameState.LOADING);
			plugin.onClientTick(new ClientTick());
			when(client.getGameState()).thenReturn(GameState.LOGGED_IN);
			plugin.onClientTick(new ClientTick());
			assertEquals("Completed", plugin.displayRaid().status);
			when(world.isInstance()).thenReturn(false);
			plugin.onGameTick(new GameTick());
			when(world.isInstance()).thenReturn(true);
			plugin.onClientTick(new ClientTick());
			assertNull(plugin.displayRaid());
			assertEquals("Completed", tracker.raids.get(0).status);
			assertEquals(100000, tracker.raids.get(0).total);
			// Capture live Ocellus transitions independently of the encounter helper.
			when(client.getTickCount()).thenReturn(100);
			callback.setTimestamp(400);
			callback.setMessage("Challenge started: Ocellus.");
			plugin.onChatMessage(callback);
			assertEquals(1, plugin.displayRaid().splits.get(0).phases.size());
			net.runelite.api.NPC boss = mock(net.runelite.api.NPC.class);
			when(boss.getId()).thenReturn(16675);
			when(boss.getWorldView()).thenReturn(mock(net.runelite.api.WorldView.class));
			when(client.getTickCount()).thenReturn(200);
			plugin.onNpcChanged(new net.runelite.api.events.NpcChanged(boss, null));
			assertEquals(1, plugin.displayRaid().splits.get(0).phases.size());
			when(boss.getWorldView()).thenReturn(world);
			plugin.onNpcChanged(new net.runelite.api.events.NpcChanged(boss, null));
			assertEquals(60000, plugin.displayRaid().splits.get(0).phases.get(0).duration);
			when(boss.getId()).thenReturn(16677);
			when(client.getTickCount()).thenReturn(300);
			plugin.onNpcChanged(new net.runelite.api.events.NpcChanged(boss, null));
			when(boss.getAnimation()).thenReturn(14859);
			net.runelite.api.events.AnimationChanged animation = new net.runelite.api.events.AnimationChanged();
			animation.setActor(boss);
			for (int tick : new int[] {340, 340, 370, 400})
			{
				when(client.getTickCount()).thenReturn(tick);
				plugin.onAnimationChanged(animation);
			}
			assertEquals(4, plugin.displayRaid().splits.get(0).phases.size());
			callback.setTimestamp(610);
			callback.setMessage("Challenge complete: Ocellus. Duration: 3:30.00. Total: 5:10.00");
			plugin.onChatMessage(callback);
			assertEquals(30000, plugin.displayRaid().splits.get(0).phases.get(3).duration);
		}
		finally
		{
			SwingUtilities.invokeAndWait(plugin::shutDown);
			verify(overlays).add(overlay);
			verify(overlays).remove(overlay);
			assertNull(plugin.displayRaid());
		}
	}
}

package com.tfasplitstracker;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class TfaTimingTest
{
	private final TfaSplitsTrackerConfig config = new TfaSplitsTrackerConfig() { };

	private TfaTracker completedRoom()
	{
		TfaTracker tracker = new TfaTracker();
		tracker.accept("Challenge started: Archive Guardian.", 100000);
		tracker.accept("Challenge complete: Archive Guardian. Duration: 0:59.40. Total: 1:02.40", 162000);
		return tracker;
	}

	@Test
	public void roomMessageUsesServerTimeAndDoesNotRepeatForRosterUpdates()
	{
		TfaRaid raid = completedRoom().current();
		assertEquals("TFA: Archive Guardian - 0:59.40 (raid split 1:02.40)", TfaTiming.messages(null, raid, config).get(0));
		TfaRaid before = raid.copy();
		raid.members.add("Raider");
		assertTrue(TfaTiming.messages(before, raid, config).isEmpty());
	}

	@Test
	public void finalRoomAndOverallMessageAnnounceTotalOnlyOnceInEitherOrder()
	{
		for (boolean totalFirst : new boolean[] {true, false})
		{
			TfaTracker tracker = completedRoom();
			String room = "Challenge complete: Ocellus. Duration: 2:00.00. Total: 8:00.00";
			String total = "The Fractured Archive: Total completion time: 8:00.00";
			TfaRaid before = tracker.current().copy();
			tracker.accept(totalFirst ? total : room, 580000);
			assertEquals(totalFirst ? 1 : 2, TfaTiming.messages(before, tracker.raids.get(0), config).size());
			before = tracker.raids.get(0).copy();
			tracker.accept(totalFirst ? room : total, 580000);
			assertEquals(totalFirst ? 1 : 0, TfaTiming.messages(before, tracker.raids.get(0), config).size());
		}
	}

	@Test
	public void chatSettingsAreIndependent()
	{
		TfaRaid raid = completedRoom().current();
		raid.status = "Completed";
		TfaSplitsTrackerConfig totalOnly = new TfaSplitsTrackerConfig() {
			@Override public boolean chatSplits() { return false; }
		};
		assertEquals(1, TfaTiming.messages(null, raid, totalOnly).size());
		TfaSplitsTrackerConfig neither = new TfaSplitsTrackerConfig() {
			@Override public boolean chatSplits() { return false; }
			@Override public boolean chatTotal() { return false; }
		};
		assertTrue(TfaTiming.messages(null, raid, neither).isEmpty());
		assertEquals(59400, raid.splits.get(0).duration);
	}

	@Test
	public void chatPersonalBestIsOptionalAndOnlyAppendsToEnabledMessages()
	{
		TfaRaid raid = completedRoom().current();
		TfaPersonalBest.select(raid, java.util.Arrays.asList(TfaPersonalBestTest.saved(3, 10000), raid));
		// Scale must be confirmed before a reference can be selected.
		assertNull(raid.personalBest);
		raid.teamSize = 3;
		TfaPersonalBest.select(raid, java.util.Arrays.asList(TfaPersonalBestTest.saved(3, 10000), raid));
		assertNotNull(raid.personalBest);
		TfaSplitsTrackerConfig comparisons = new TfaSplitsTrackerConfig() {
			@Override public boolean chatPersonalBest() { return true; }
		};
		assertFalse(config.chatPersonalBest());
		assertEquals(1, TfaTiming.messages(null, raid, config).size());
		assertFalse(TfaTiming.messages(null, raid, config).get(0).contains("PB"));
		assertEquals(1, TfaTiming.messages(null, raid, comparisons).size());
		assertTrue(TfaTiming.messages(null, raid, comparisons).get(0).contains("vs scale 3 PB"));
		TfaRaid before = raid.copy();
		raid.status = "Completed";
		assertTrue(TfaTiming.messages(before, raid, comparisons).get(0).contains("vs scale 3 PB"));
		assertTrue(TfaTiming.messages(raid.copy(), raid, comparisons).isEmpty());
		TfaSplitsTrackerConfig silent = new TfaSplitsTrackerConfig() {
			@Override public boolean chatPersonalBest() { return true; }
			@Override public boolean chatSplits() { return false; }
			@Override public boolean chatTotal() { return false; }
		};
		assertTrue(TfaTiming.messages(null, raid, silent).isEmpty());
	}

	@Test
	public void liveRaidClockReadsHudTextWithoutExtrapolation()
	{
		assertEquals(65400, TfaLiveState.parseClock("<col=ffffff>1:05.40</col>"));
		assertEquals(65400, TfaLiveState.parseClock("Raid time: 1:05.40"));
		assertEquals(3725400, TfaLiveState.parseClock("1:02:05.40"));
		assertEquals(65000, TfaLiveState.parseClock("1:05"));
		assertEquals(-1, TfaLiveState.parseClock("-"));
		assertEquals(-1, TfaLiveState.parseClock(null));
	}

	@Test
	public void leavingClosesOnlyActiveRaidsAndPreservesRecordedTimes()
	{
		TfaTracker tracker = completedRoom();
		assertTrue(tracker.leaveRaid());
		assertNull(tracker.current());
		assertEquals("Left raid", tracker.raids.get(0).status);
		assertEquals(62400, tracker.raids.get(0).total);
		assertEquals(59400, tracker.raids.get(0).splits.get(0).duration);
		assertFalse(tracker.leaveRaid());
		for (String status : new String[] {"Completed", "Failed", "Abandoned"})
		{
			tracker.raids.get(0).status = status;
			assertFalse(tracker.leaveRaid());
			assertEquals(status, tracker.raids.get(0).status);
		}
	}

	@Test
	public void infoboxTextAndTooltipRespondToSettings()
	{
		TfaSplitsTrackerPlugin plugin = mock(TfaSplitsTrackerPlugin.class);
		TfaSplitsTrackerConfig settings = mock(TfaSplitsTrackerConfig.class);
		when(settings.infoBoxText()).thenReturn(TfaSplitsTrackerConfig.InfoBoxText.ROOM_TIME);
		when(settings.showInfoBoxes()).thenReturn(true);
		when(plugin.timingVisible()).thenReturn(true);
		TfaSplitInfoBox box = new TfaSplitInfoBox(plugin, settings, completedRoom().current().splits.get(0));
		assertEquals("0:59", box.getText());
		assertTrue(box.render());
		assertEquals("", box.getTooltip());
		when(settings.infoBoxText()).thenReturn(TfaSplitsTrackerConfig.InfoBoxText.CUMULATIVE);
		when(settings.infoBoxTooltip()).thenReturn(true);
		when(settings.infoBoxCumulative()).thenReturn(true);
		assertEquals("1:02", box.getText());
		assertTrue(box.getTooltip().contains("Room time: 0:59.40<br>Raid split: 1:02.40"));
		when(settings.infoBoxText()).thenReturn(TfaSplitsTrackerConfig.InfoBoxText.NONE);
		when(settings.showInfoBoxes()).thenReturn(false);
		assertEquals("", box.getText());
		assertFalse(box.render());
	}

}

package com.tfasplitstracker;

import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.*;

public class TfaTrackerTest
{
	static final class Event
	{
		long timestamp;
		String message;
	}

	static final class RecordedRaid
	{
		int teamSize;
		String expectedTotal;
		Event[] events;
	}

	static RecordedRaid[] recordings() throws Exception
	{
		try (InputStreamReader reader = new InputStreamReader(TfaTrackerTest.class.getResourceAsStream("recorded-raids.json"), StandardCharsets.UTF_8))
		{
			return new Gson().fromJson(reader, RecordedRaid[].class);
		}
	}

	@Test
	public void replayServerMessagesForThreeFourFiveAndSixPlayers() throws Exception
	{
		Set<Integer> sizes = new HashSet<>();
		for (RecordedRaid recording : recordings())
		{
			TfaTracker tracker = new TfaTracker();
			for (Event event : recording.events)
			{
				assertTrue(event.message, tracker.accept(event.message, event.timestamp));
				assertFalse("Duplicate event", tracker.accept(event.message, event.timestamp));
			}
			assertNull(tracker.current());
			assertEquals(1, tracker.raids.size());
			TfaRaid raid = tracker.raids.get(0);
			assertEquals("Completed", raid.status);
			assertEquals(recording.expectedTotal, TfaRaid.time(raid.total));
			assertEquals(recording.teamSize, raid.teamSize);
			assertTrue(raid.completeSplits());
			assertEquals(5, raid.splits.size());
			assertTrue("Overall includes transitions", raid.total > raid.combatTime());
			for (TfaRaid.Split split : raid.splits)
			{
				Event completion = Arrays.stream(recording.events).filter(e -> e.message.startsWith("Challenge complete: " + split.room + ".")).findFirst().get();
				String plain = completion.message.replaceAll("<[^>]*>", "");
				assertTrue(plain, plain.contains("Duration: " + TfaRaid.time(split.duration) + ". Total: " + TfaRaid.time(split.cumulative)));
			}
			sizes.add(raid.teamSize);
		}
		assertEquals(new HashSet<>(Arrays.asList(3, 4, 5, 6)), sizes);
	}

	@Test
	public void recoverWithoutAnyStartCallbacks() throws Exception
	{
		RecordedRaid recording = recordings()[0];
		TfaTracker tracker = new TfaTracker();
		for (Event event : recording.events)
		{
			if (!event.message.startsWith("Challenge started:"))
			{
				tracker.accept(event.message, event.timestamp);
			}
		}
		assertEquals(1, tracker.raids.size());
		assertEquals(recording.expectedTotal, TfaRaid.time(tracker.raids.get(0).total));
		assertTrue(tracker.raids.get(0).completeSplits());
	}

	@Test
	public void recoverFinalTotalWithoutOcellusCallback() throws Exception
	{
		RecordedRaid recording = recordings()[0];
		TfaTracker tracker = new TfaTracker();
		for (Event event : recording.events)
		{
			if (!event.message.startsWith("Challenge complete: Ocellus"))
			{
				tracker.accept(event.message, event.timestamp);
			}
		}
		assertEquals("Completed", tracker.raids.get(0).status);
		assertEquals(recording.expectedTotal, TfaRaid.time(tracker.raids.get(0).total));
		assertFalse("Never invent a missing split", tracker.raids.get(0).completeSplits());
	}

	@Test
	public void journalSurvivesRestartAndConsecutiveRuns() throws Exception
	{
		RecordedRaid recording = recordings()[0];
		TfaTracker tracker = new TfaTracker();
		Gson gson = new Gson();
		for (Event event : recording.events)
		{
			tracker.accept(event.message, event.timestamp);
			tracker = gson.fromJson(gson.toJson(tracker), TfaTracker.class);
			assertFalse(tracker.accept(event.message, event.timestamp));
		}
		for (Event event : recording.events)
		{
			tracker.accept(event.message, event.timestamp + 86400000);
		}
		assertEquals(2, tracker.raids.size());
		assertNotEquals(tracker.raids.get(0).id, tracker.raids.get(1).id);
		assertTrue(tracker.raids.stream().allMatch(TfaRaid::completeSplits));
	}

	@Test
	public void localDeathIsNotRaidFailureAndAllEightPartySlotsAreSupported()
	{
		TfaTracker tracker = new TfaTracker();
		tracker.accept("Challenge started: Archive Guardian.", 1000);
		assertFalse(tracker.accept("You will respawn when your party completes or fails the challenge.", 2000));
		assertNotNull(tracker.current());
		assertTrue(tracker.party(Arrays.asList("One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight")));
		assertFalse(tracker.party(Arrays.asList("oNe", "Two", null, "")));
		assertEquals(8, tracker.current().members.size());
		tracker.accept("You failed to survive the Fractured Archive.", 3000);
		assertNull(tracker.current());
		assertEquals("Failed", tracker.raids.get(0).status);
		tracker.accept("Challenge started: Archive Guardian.", 4000);
		tracker.accept("You abandon the raid and leave the Fractured Archive.", 5000);
		assertEquals("Abandoned", tracker.raids.get(0).status);
		assertEquals(2, tracker.raids.size());
	}

	@Test
	public void detectNewRunEvenWhenItsFirstStartWasMissed()
	{
		TfaTracker tracker = new TfaTracker();
		tracker.accept("Challenge started: Archive Guardian.", 1000);
		tracker.accept("Challenge complete: Archive Guardian. Duration: 2:00.00. Total: 2:00.00", 121000);
		tracker.accept("Challenge started: Bork.", 130000);
		tracker.accept("Challenge complete: Archive Guardian. Duration: 1:58.20. Total: 1:58.20", 400000);
		assertEquals(2, tracker.raids.size());
		assertEquals("Interrupted", tracker.raids.get(1).status);
		assertEquals("1:58.20", TfaRaid.time(tracker.current().total));
	}

	@Test
	public void supportHourLongRunsAndRepeatedFirstRoomAttempts()
	{
		TfaTracker tracker = new TfaTracker();
		tracker.accept("Challenge started: Archive Guardian.", 1000);
		tracker.accept("Challenge started: Archive Guardian.", 180000);
		assertEquals(2, tracker.raids.size());
		assertEquals("Interrupted", tracker.raids.get(1).status);
		tracker.accept("The Fractured Archive: Total completion time: 1:03:35.40. Personal best: 23:19.20", 4000000);
		assertEquals("Completed", tracker.raids.get(0).status);
		assertEquals(3815400, tracker.raids.get(0).total);
	}

	@Test
	public void deletedRaidStaysDeletedAfterPersistenceAndChatReplay() throws Exception
	{
		RecordedRaid recording = recordings()[0];
		TfaTracker tracker = new TfaTracker();
		for (Event event : recording.events)
		{
			tracker.accept(event.message, event.timestamp);
		}
		String id = tracker.raids.get(0).id;
		assertTrue(tracker.delete(id, null));
		assertTrue(tracker.raids.isEmpty());
		tracker = new Gson().fromJson(new Gson().toJson(tracker), TfaTracker.class);
		for (Event event : recording.events)
		{
			assertFalse(tracker.accept(event.message, event.timestamp));
		}
		assertTrue(tracker.raids.isEmpty());
		assertTrue(tracker.undoDelete());
		assertEquals(id, tracker.raids.get(0).id);
		assertEquals(recording.expectedTotal, TfaRaid.time(tracker.raids.get(0).total));
		assertFalse(tracker.undoDelete());
	}

	@Test
	public void deleteRoomPreservesServerTotalAndUndoRestoresCompleteHistory() throws Exception
	{
		RecordedRaid recording = recordings()[0];
		TfaTracker tracker = new TfaTracker();
		for (Event event : recording.events)
		{
			tracker.accept(event.message, event.timestamp);
		}
		TfaRaid raid = tracker.raids.get(0);
		assertFalse(tracker.delete(raid.id, "Not a room"));
		assertTrue(tracker.delete(raid.id, "Bork"));
		assertFalse(raid.completeSplits());
		assertEquals(4, raid.splits.size());
		assertEquals(recording.expectedTotal, TfaRaid.time(raid.total));
		assertTrue(tracker.undoDelete());
		assertTrue(tracker.raids.get(0).completeSplits());
	}

	@Test
	public void resettingActiveRunSuppressesRemainingEventsUntilNextRaid() throws Exception
	{
		RecordedRaid recording = recordings()[0];
		TfaTracker tracker = new TfaTracker();
		Event start = recording.events[0];
		tracker.accept(start.message, start.timestamp);
		assertFalse(tracker.delete(tracker.current().id, "Archive Guardian"));
		assertTrue(tracker.delete(tracker.current().id, null));
		assertNull(tracker.current());
		tracker = new Gson().fromJson(new Gson().toJson(tracker), TfaTracker.class);
		for (Event event : recording.events)
		{
			tracker.accept(event.message, event.timestamp);
		}
		assertTrue(tracker.raids.isEmpty());
		assertFalse(tracker.undoDelete());
		tracker.accept(start.message, start.timestamp + 86400000);
		assertNotNull(tracker.current());
		assertFalse(tracker.suppressUntilNextRaid);
	}

	@Test
	public void undoOldDeletionDoesNotReplaceNewActiveRun() throws Exception
	{
		RecordedRaid recording = recordings()[0];
		TfaTracker tracker = new TfaTracker();
		for (Event event : recording.events)
		{
			tracker.accept(event.message, event.timestamp);
		}
		tracker.delete(tracker.raids.get(0).id, null);
		tracker.accept("Challenge started: Archive Guardian.", recording.events[0].timestamp + 86400000);
		String active = tracker.current().id;
		tracker.undoDelete();
		assertEquals(active, tracker.current().id);
		assertEquals(2, tracker.raids.size());
	}

	@Test
	public void recognizeAlternativeBossNamesWithoutChangingStoredKeys()
	{
		TfaTracker tracker = new TfaTracker();
		tracker.accept("Challenge started: Archive Guardian.", 1000);
		tracker.accept("Challenge complete: Archive Guardian. Duration: 1:00.00. Total: 1:00.00", 61000);
		tracker.accept("Challenge started: Bork and the Smorks.", 62000);
		tracker.accept("Challenge complete: Bork and the Smorks. Duration: 1:00.00. Total: 2:01.00", 122000);
		tracker.accept("Challenge started: Moia.", 123000);
		tracker.accept("Challenge complete: Moia. Duration: 1:00.00. Total: 3:02.00", 183000);
		tracker.accept("Challenge started: Dagon'hai Elder and monks.", 184000);
		tracker.accept("Challenge complete: Dagon'hai Elder and monks. Duration: 1:00.00. Total: 4:03.00", 244000);
		tracker.accept("Challenge started: Ocellus.", 245000);
		tracker.accept("Challenge complete: Ocellus. Duration: 1:00.00. Total: 5:04.00", 305000);
		TfaRaid raid = tracker.raids.get(0);
		assertTrue(raid.completeSplits());
		assertEquals("Bork", raid.splits.get(1).room);
		assertEquals("Dagon'hai Trio", raid.splits.get(3).room);
		assertEquals(TfaRoom.DAGONHAI, TfaRoom.find("Dagon’hai Elder and monks"));
		assertEquals(5, raid.splits.size());
	}

	@Test
	public void ignoreOtherRaidsAndClanBroadcastsAndMarkMissingRooms()
	{
		TfaTracker tracker = new TfaTracker();
		assertFalse(tracker.accept("Challenge started: Akkha.", 1000));
		assertFalse(tracker.accept("Challenge complete: Akkha. Duration: 1:20.40. Total: 4:10.80", 2000));
		assertFalse(tracker.accept("Someone has achieved a new The Fractured Archive (team size: 5) Normal mode Overall personal best: 23:19.20", 3000));
		assertTrue(tracker.raids.isEmpty());
		tracker.accept("Challenge complete: Ocellus. Duration: <col=ef1020>9:23.40</col>. Total: <col=ef1020>19:16.20</col> (new personal best)", 2000000);
		assertEquals(1156200, tracker.raids.get(0).total);
		assertFalse(tracker.raids.get(0).completeSplits());
	}
}
